#!/bin/zsh

export P12_BASE64=""
export P12_PASSWORD="12345678"
export MOBILEPROVISION_BASE64=""

echo "P12_BASE64: $P12_BASE64"
echo "P12_PASSWORD: $P12_PASSWORD"
echo "MOBILEPROVISION_BASE64: $MOBILEPROVISION_BASE64"

echo "$MOBILEPROVISION_BASE64" | base64 --decode > ~/Library/MobileDevice/Provisioning\ Profiles/profile.mobileprovision
echo ">>>>>"
ls -la ~/Library/MobileDevice/Provisioning\ Profiles
#cat ~/Library/MobileDevice/Provisioning\ Profiles/profile.mobileprovision
echo "<<<<<"

xcodebuild clean archive \
  -project ../SMOC.xcodeproj \
  -scheme SMOC \
  -configuration Release \
  -archivePath build/YourApp.xcarchive


exit

xcodebuild clean archive \
          -scheme SMOC \
          -configuration Debug \
          -archivePath build/MyApp.xcarchive \
          -destination "generic/platform=iOS" \
          CODE_SIGN_STYLE=Manual \
          PROVISIONING_PROFILE_SPECIFIER="SMOC_Dev" \
          DEVELOPMENT_TEAM="7ZPDPWR8XU" \
          CODE_SIGN_IDENTITY="Apple Development"
